/* AI mode: story text and illustration generated by OpenAI over WiFi.
 * Only built with -DWITH_GPT=ON (HADISTORY_WITH_GPT=1).
 * The WiFi connection is started on demand and runs in the background: the main loop
 * polls gpt_wifi_poll() and only enters the AI mode once the link is up.
 */
#ifndef HADISTORY_GPT_H
#define HADISTORY_GPT_H

#include <stdbool.h>

typedef enum {
    WIFI_OFF = 0,       // no connection attempted, or link lost
    WIFI_CONNECTING,
    WIFI_UP,
    WIFI_FAILED,        // last attempt failed (timeout, no network, bad password)
} wifi_state_t;

void gpt_init(void);                 // station mode on, no connection yet
void gpt_wifi_connect(void);         // start a connection attempt in the background
wifi_state_t gpt_wifi_poll(void);    // advance and return the connection state, logs transitions
bool gpt_wifi_up(void);
bool gpt_generate_page(void);        // full pipeline, needs the WiFi up
const char *gpt_wifi_state_name(wifi_state_t s);

#endif
